async def reconnect(self) -> None: self._reconnect_count = 0 max_attempts = 10
while self._reconnect_count < max_attempts: self._reconnect_count += 1 delay = min( self.config.reconnect_delay * (2 ** (self._reconnect_count - 1)), self.config.reconnect_max_delay, ) await asyncio.sleep(delay)
try: await self.connect() for symbol, channels in self._subscriptions.items(): await self.subscribe([symbol], list(channels)) self._reconnect_count = 0 return except Exception as e: logger.warning("lighter_reconnect_failed", error=str(e))
raise LighterConnectionError("Max reconnection attempts reached")


@pytest.mark.integration
@skip_without_lighter_creds
class TestLighterStreamIntegration:
    async def test_connect_and_subscribe(self, adapter):
        await adapter.subscribe(["BTC-PERP"], ["trades"])
        assert adapter.is_connected()
